import numpy as np,cv2
f=np.load('.tmp/full.npy')[0]
for nm,x,y in [('blue',839,289),('red',704,341),('white',533,407)]:
 im=f[y-35:y+30,x-45:x+45].astype(float);r,g,b=im.transpose(2,0,1)
 if nm=='blue':m=(b>r*1.45)&(b>g*1.1)&(b>70)
 elif nm=='red':m=(r>g*1.35)&(r>b*1.22)&(r>150)
 else:m=(g>180)&(np.max(im,2)-np.min(im,2)<35)
 n,l,st,c=cv2.connectedComponentsWithStats(m.astype('uint8'));k=1+np.argmax(st[1:,4]);m=(l==k).astype('uint8')
 print(nm,st[k]+np.array([x-45,y-35,0,0,0]),c[k]+[x-45,y-35])
 cv2.imwrite('.tmp/'+nm+'_mask.png',m*255)
PY"
